const response = $input.first();
const html = response.json.data || response.data || response.body || '';
const headers = response.json.headers || response.headers || {};

if (!html || typeof html !== 'string') {
  return { error: 'No HTML data received' };
}

let setCookie = headers['set-cookie'] || headers['Set-Cookie'] || [];
if (!Array.isArray(setCookie)) setCookie = [setCookie];
const cookieStr = setCookie.map((c) => c.split(';')[0]).join('; ');

const patterns = [
  /name="__RequestVerificationToken"[^>]*value="([^"]+)"/i,
  /value="([^"]+)"[^>]*name="__RequestVerificationToken"/i,
  /__RequestVerificationToken.*?value="([^"]+)"/
];
let tokenMatch;
for (let pattern of patterns) {
  tokenMatch = html.match(pattern);
  if (tokenMatch) break;
}
if (!tokenMatch || !tokenMatch[1]) {
  return { error: 'Token CSRF no encontrado' };
}
return { csrfToken: tokenMatch[1], cookie: cookieStr };

const postLoginResponse = $input.first();
const headers = postLoginResponse.json.headers || {};
const prevCookie = $('Extraer Token CSRF').first().json.cookie || '';

let setCookie = headers['set-cookie'] || headers['Set-Cookie'] || [];
if (!Array.isArray(setCookie)) setCookie = [setCookie];
const newCookies = setCookie.map((c) => c.split(';')[0]);

const merged = {};
prevCookie.split('; ').filter(Boolean).forEach((c) => {
  const [k, v] = c.split('=');
  merged[k] = v;
});
newCookies.forEach((c) => {
  const [k, v] = c.split('=');
  merged[k] = v;
});

const cookieStr = Object.entries(merged).map(([k, v]) => `${k}=${v}`).join('; ');

return { cookie: cookieStr };

const response = $input.first();
const html = response.json.data || response.data || response.body || '';

if (!html || typeof html !== 'string') {
  return { success: false, error: 'No HTML data received', polizas: [] };
}

let data = [];
const patterns = [
  /var\s+dataSource\s*=\s*(\[.*?\]);/s,
  /datasource['"]?\s*:\s*(\[.*?\])/is,
  /\{\s*"Data"\s*:\s*(\[.*?\])\s*\}/s
];

for (const pattern of patterns) {
  const match = html.match(pattern);
  if (match && match[1]) {
    try {
      data = JSON.parse(match[1]);
      if (Array.isArray(data)) break;
    } catch (e) {
      continue;
    }
  }
}

if (!Array.isArray(data)) {
  return { success: false, error: 'No data array found in HTML', polizas: [] };
}

const motivos_excluir = ['Cambio forma de pago'];
const productores_excluir = ['FASANELLA', 'LIJO', 'CALARCO', 'MAGNAGHI'];
const polizas = [];

for (const item of data) {
  const motivo = item.TipoEndosoDescripcion || '';
  const productor = item.ProductorPrincipalDescripcion || '';
  const poliza = item.Poliza || '';
  const idCotizacion = item.CotizacionId;
  let excluir = false;
  if (motivos_excluir.some(m => motivo.toUpperCase().includes(m.toUpperCase()))) excluir = true;
  if (productores_excluir.some(p => productor.toUpperCase().includes(p.toUpperCase()))) excluir = true;
  if (!excluir && poliza && idCotizacion) {
    polizas.push({
      ramo: item.RamoDescripcion || '',
      poliza: poliza,
      endoso: item.NumeroEndoso || '',
      productor: productor,
      motivo: motivo,
      idCotizacion: idCotizacion
    });
  }
}

return { success: true, polizas };

const response = $input.first();
const itemData = $('Item Lists').first().json;
let html = response.json.data || response.data || response.body || '';
if (!html) return { ...itemData, calle: '', altura: '', provincia: '', sumaAsegurada: '' };
const riesgosMatch = html.match(/<table[^>]*>([\s\S]*?)<\/table>/);
if (!riesgosMatch) return { ...itemData, calle: '', altura: '', provincia: '', sumaAsegurada: '' };
const tableHtml = riesgosMatch[1];
const rowRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/g;
let rowMatch;
let calle = '', altura = '', provincia = '', sumaAsegurada = '';
while ((rowMatch = rowRegex.exec(tableHtml)) !== null) {
  const row = rowMatch[1];
  const cellRegex = /<td[^>]*>([\s\S]*?)<\/td>/g;
  const cells = [];
  let cellMatch;
  while ((cellMatch = cellRegex.exec(row)) !== null) {
    let content = cellMatch[1].replace(/<[^>]*>/g, '').trim();
    cells.push(content);
  }
  if (cells.length > 0 && cells[0].includes('INCENDIO EDIFICIO')) {
    sumaAsegurada = cells[2] || '';
  }
  if (cells.length >= 7) {
    calle = cells[6] || calle;
    altura = cells[7] || altura;
    provincia = cells[4] || provincia;
  }
}
return { ...itemData, calle, altura, provincia, sumaAsegurada };

const data = $input.first();
return {
  Productor: data.productor || '',
  Poliza: data.poliza || '',
  Endoso: data.endoso || '',
  Calle: data.calle || '',
  Altura: data.altura || '',
  Provincia: data.provincia || '',
  Suma_Asegurada: data.sumaAsegurada || ''
};
